
(function(){
 const F=['data:image/jpeg;base64,','data:image/jpeg;base64,','data:image/jpeg;base64,'];
 function forceCars110(){
  try{
   const card=document.querySelector('.replay-main-card');
   if(!card)return;
   const head=card.querySelector('.replay-question-head span');
   if(!head||!/^CARS1\.10\b/.test((head.textContent||'').trim()))return;
   const stage=card.querySelector('[data-standard-video]');
   if(!stage)return;
   const img=stage.querySelector('.replay-local-freeze img');
   if(!img)return;
   let phase=0;
   const m=(stage.className||'').match(/phase-(\d)/);
   if(m)phase=Math.max(0,Math.min(2,Number(m[1])));
   const wanted=F[phase]||F[0];
   if(img.src!==wanted)img.src=wanted;
  }catch(_){}
 }
 const obs=new MutationObserver(forceCars110);
 obs.observe(document.documentElement,{subtree:true,childList:true,attributes:true,attributeFilter:['class','src']});
 forceCars110();
 setTimeout(forceCars110,0);setTimeout(forceCars110,100);setTimeout(forceCars110,500);
})();
